const calS=y=>({lv:` Kalendārā kopš ${y}. gada.`,ru:` В календаре с ${y} года.`,en:` In the calendar since ${y}.`,lt:` Kalendoriuje nuo ${y} metų.`,et:` Kalendris alates ${y}. aastast.`});
const rec=(place,when,calYear)=>{let s;
 if(!place){s={lv:'',ru:'',en:'',lt:'',et:''};}
 else{const p=P[place],y=typeof when==='number',q=when&&!y?Q[when]:null,cap=x=>x.charAt(0).toUpperCase()+x.slice(1);
  s={lv:`${p[0]} vārds pierakstīts${y?' '+when+'. gadā':q?' '+q[0]:''}.`,ru:`${cap(p[1])} имя записано${y?' в '+when+' году':q?' '+q[1]:''}.`,en:`It is recorded in ${p[2]}${y?' in '+when:q?' '+q[2]:''}.`,lt:`${p[3]} vardas užrašytas${y?' '+when+' metais':q?' '+q[3]:''}.`,et:`${p[4]} on nimi kirja pandud${y?' '+when+'. aastal':q?' '+q[4]:''}.`};}
 if(calYear){const c=calS(calYear);for(const l of L)s[l]=(s[l]+c[l]).trim();}
 return s;};
const T={
 form:(n,b)=>[`${n} ir vārda ${b} forma.`,`${n} — форма имени ${b}.`,`${n} is a form of ${b}.`,`${n} – vardo ${b} forma.`,`${n} on nime ${b} kuju.`],
 deriv:(n,b)=>[`${n} ir vārda ${b} atvasinājums.`,`${n} — производное от имени ${b}.`,`${n} is derived from ${b}.`,`${n} – vardo ${b} vedinys.`,`${n} on tuletatud nimest ${b}.`],
 fem:(n,b)=>[`${n} ir vārda ${b} sieviešu forma.`,`${n} — женская форма имени ${b}.`,`${n} is the feminine form of ${b}.`,`${n} – moteriška vardo ${b} forma.`,`${n} on nime ${b} naisekuju.`],
 masc:(n,b)=>[`${n} ir vārda ${b} vīriešu forma.`,`${n} — мужская форма имени ${b}.`,`${n} is the masculine form of ${b}.`,`${n} – vyriška vardo ${b} forma.`,`${n} on nime ${b} mehekuju.`],
 form2:(n,a,b)=>[`${n} ir vārdu ${a} un ${b} forma.`,`${n} — форма имён ${a} и ${b}.`,`${n} is a form of ${a} and ${b}.`,`${n} – vardų ${a} ir ${b} forma.`,`${n} on nimede ${a} ja ${b} kuju.`],
 short2:(n,a,b)=>[`${n} ir vārdu ${a} un ${b} saīsinājums.`,`${n} — сокращение имён ${a} и ${b}.`,`${n} is a short form of ${a} and ${b}.`,`${n} – vardų ${a} ir ${b} trumpinys.`,`${n} on nimede ${a} ja ${b} lühivorm.`],
 enForm:(n,b)=>[`${n} ir vārda ${b} angļu forma.`,`${n} — английская форма имени ${b}.`,`${n} is the English form of ${b}.`,`${n} – angliška vardo ${b} forma.`,`${n} on nime ${b} inglise kuju.`],
 // Germanic compound: [a, gloss5], [b, gloss5]
 ohg:(n,a,ga,b,gb)=>[`${n} darināts no senaugšvācu ${a} — «${ga[0]}» — un ${b} — «${gb[0]}».`,`${n} образовано от древневерхненемецких ${a} — «${ga[1]}» — и ${b} — «${gb[1]}».`,`${n} is formed from Old High German ${a}, “${ga[2]}”, and ${b}, “${gb[2]}”.`,`${n} sudarytas iš senosios aukštaičių vokiečių ${a} – „${ga[3]}“ – ir ${b} – „${gb[3]}“.`,`${n} on moodustatud vanaülemsaksa sõnadest ${a}, „${ga[4]}”, ja ${b}, „${gb[4]}”.`],
 greek:(n,w,g)=>[`${n} cēlies no grieķu ${w} — «${g[0]}».`,`${n} восходит к греческому ${w} — «${g[1]}».`,`${n} comes from Greek ${w}, “${g[2]}”.`,`${n} kilęs iš graikų ${w} – „${g[3]}“.`,`${n} pärineb kreeka sõnast ${w}, „${g[4]}”.`],
 latin:(n,w,g)=>[`${n} cēlies no latīņu ${w} — «${g[0]}».`,`${n} восходит к латинскому ${w} — «${g[1]}».`,`${n} comes from Latin ${w}, “${g[2]}”.`,`${n} kilęs iš lotynų ${w} – „${g[3]}“.`,`${n} pärineb ladina sõnast ${w}, „${g[4]}”.`]};
const G={spear:['šķēps','копьё','spear','ietis','oda'],strong:['stiprs, drosmīgs','сильный, смелый','strong, brave','stiprus, drąsus','tugev, julge'],rule:['valdīt','править','to rule','valdyti','valitsema'],famous:['slavens','славный','famous','garsus','kuulus'],noble:['dižciltīgs','знатный','noble','kilmingas','üllas'],god:['dievs','бог','god','dievas','jumal'],peace:['miers','мир','peace','taika','rahu'],battle:['cīņa','битва','battle','kova','võitlus'],army:['karaspēks','войско','army','kariuomenė','sõjavägi']};
